ЗагСупа.Вставить("Accept", "application/json");

Результат = "=== Миграция Git в Supabase ===" + Символы.ПС;
Успех = 0;
Ошибок = 0;
ДеревоПолучено = Ложь;
Файлы = Новый Массив;

// --- Шаг 1: Дерево файлов ---
Попытка
    ПутьДерева = "/repos/" + Репозиторий + "/git/trees/" + Ветка + ":" + КаталогЗнаний + "?recursive=1";
    ЗапросДерева = Новый HTTPЗапрос(ПутьДерева, ЗагГит);
    ОтветДерева = Гит.Получить(ЗапросДерева);
    Если ОтветДерева.КодСостояния = 200 Тогда
        Чт = Новый ЧтениеJSON;
        Чт.УстановитьСтроку(ОтветДерева.ПолучитьТелоКакСтроку());
        Дерево = ПрочитатьJSON(Чт, Ложь);
        Чт.Закрыть();
        Для Каждого Эл Из Дерево.tree Цикл
            Если Эл.type = "blob" И НРег(Прав(Эл.path, 5)) = ".json" Тогда
                Файлы.Добавить(Эл.path);
            КонецЕсли;
        КонецЦикла;
        ДеревоПолучено = Истина;
        Результат = Результат + "Найдено JSON: " + Строка(Файлы.Количество()) + Символы.ПС;
    Иначе
        Результат = Результат + "ОШИБКА дерева: HTTP " + Строка(ОтветДерева.КодСостояния) + Символы.ПС;
    КонецЕсли;
Исключение
    Результат = Результат + "ОШИБКА дерева: " + ОписаниеОшибки() + Символы.ПС;
КонецПопытки;

// --- Шаг 2: Диагностика первого файла ---
Если ДеревоПолучено И Файлы.Количество() > 0 Тогда
    ПутьФайла = Файлы[0];
    Результат = Результат + Символы.ПС + "--- Диагностика: " + ПутьФайла + " ---" + Символы.ПС;
    Попытка
        ПутьКонт = "/repos/" + Репозиторий + "/contents/" + ПутьФайла;
        ЗапФайла = Новый HTTPЗапрос(ПутьКонт, ЗагГитRaw);
        ОтвФайла = Гит.Получить(ЗапФайла);
        Результат = Результат + "HTTP Git: " + Строка(ОтвФайла.КодСостояния) + Символы.ПС;
        Если ОтвФайла.КодСостояния = 200 Тогда
            ТелоФайла = ОтвФайла.ПолучитьТелоКакСтроку();
            Результат = Результат + "Длина: " + Строка(СтрДлина(ТелоФайла)) + Символы.ПС;
