            Попытка
                Ч2 = Новый ЧтениеJSON;
                Ч2.УстановитьСтроку(ТелоФайла);
                Обр = ПрочитатьJSON(Ч2, Ложь);
                Ч2.Закрыть();
                Ключи = "";
                Для Каждого КЗ Из Обр Цикл
                    Ключи = Ключи + КЗ.Ключ + "; ";
                КонецЦикла;
                Результат = Результат + "Ключи: " + Ключи + Символы.ПС;
                Результат = Результат + "success=" + Строка(?(Обр.Свойство("success"), Обр.success, "нет")) + Символы.ПС;
                Результат = Результат + "type=" + Строка(?(Обр.Свойство("type"), Обр.type, "нет")) + Символы.ПС;
            Исключение
                Результат = Результат + "ОШИБКА JSON: " + ОписаниеОшибки() + Символы.ПС;
            КонецПопытки;
        Иначе
            Результат = Результат + "Тело: " + Лев(ОтвФайла.ПолучитьТелоКакСтроку(), 300) + Символы.ПС;
        КонецЕсли;
    Исключение
        Результат = Результат + "ОШИБКА: " + ОписаниеОшибки() + Символы.ПС;
    КонецПопытки;

    // --- Шаг 3: Тест вставки одного файла ---
    Результат = Результат + Символы.ПС + "--- Тест вставки ---" + Символы.ПС;
    Попытка
        ЗапJSON = Новый ЗаписьJSON;
        ЗапJSON.УстановитьСтроку();
        ЗапJSON.ЗаписатьНачалоМассива();
        ЗапJSON.ЗаписатьНачалоОбъекта();
        ЗапJSON.ЗаписатьИмяСвойства("fingerprint");
        ЗапJSON.ЗаписатьЗначение(?(Обр.Свойство("fingerprint"), Строка(Обр.fingerprint), ""));
        ЗапJSON.ЗаписатьИмяСвойства("task");
        ЗапJSON.ЗаписатьЗначение(?(Обр.Свойство("task"), Строка(Обр.task), ""));
        ЗапJSON.ЗаписатьИмяСвойства("code");
        ЗапJSON.ЗаписатьЗначение(?(Обр.Свойство("code"), Строка(Обр.code), ""));
        ЗапJSON.ЗаписатьИмяСвойства("lang");
        ЗапJSON.ЗаписатьЗначение(?(Обр.Свойство("lang"), Строка(Обр.lang), ""));
        ЗапJSON.ЗаписатьИмяСвойства("result");
        ЗапJSON.ЗаписатьЗначение(?(Обр.Свойство("result"), Строка(Обр.result), ""));
        ЗапJSON.ЗаписатьИмяСвойства("success");
        ЗапJSON.ЗаписатьЗначение(?(Обр.Свойство("success"), Обр.success, Ложь));
        ЗапJSON.ЗаписатьИмяСвойства("type");
        ЗапJSON.ЗаписатьЗначение(?(Обр.Свойство("type"), Строка(Обр.type), ""));
        ЗапJSON.ЗаписатьИмяСвойства("timestamp");
        ЗапJSON.ЗаписатьЗначение(Формат(ТекущаяДата(), "ДФ=yyyy-MM-ddTHH:mm:ssZ"));
        ЗапJSON.ЗаписатьКонецОбъекта();
        ЗапJSON.ЗаписатьКонецМассива();
        ТелоВст = ЗапJSON.Закрыть();

        Результат = Результат + "Тело запроса: " + Лев(ТелоВст, 500) + Символы.ПС;

        ЗапВст = Новый HTTPЗапрос("/rest/v1/knowledge", ЗагСупа);
        ЗапВст.УстановитьТелоИзСтроки(ТелоВст, КодировкаТекста.UTF8, ИспользованиеByteOrderMark.НеИспользовать);
        ОтвВст = Супа.ОтправитьДляОбработки(ЗапВст);

        Результат = Результат + "INSERT HTTP: " + Строка(ОтвВст.КодСостояния) + Символы.ПС;
        Если ОтвВст.КодСостояния >= 200 И ОтвВст.КодСостояния < 300 Тогда
            Результат = Результат + "Вставка УСПЕХ" + Символы.ПС;
            Успех = Успех + 1;
        Иначе
            Результат = Результат + "Ответ: " + Лев(ОтвВст.ПолучитьТелоКакСтроку(), 500) + Символы.ПС;
            Ошибок = Ошибок + 1;
        КонецЕсли;
    Исключение
        Результат = Результат + "ОШИБКА вставки: " + ОписаниеОшибки() + Символы.ПС;
        Ошибок = Ошибок + 1;
    КонецПопытки;

    // Очистка тестовой записи
    Попытка
        ЗапУдал = Новый HTTPЗапрос("/rest/v1/knowledge?fingerprint=eq." + Строка(Обр.fingerprint), ЗагСупа);
        Супа.Удалить(ЗапУдал);
    Исключение
    КонецПопытки;
КонецЕсли;

Результат = Результат + Символы.ПС + "=== Диагностика завершена ===";
